class Document
  def initialize(path)
    @parts = []                    # parts: never exposed to clients
    @io = File.open(path, "w+")    # owned resource
  end
  def add(text) = @parts << Paragraph.new(text)
  def close                        # the only release path: cascades to parts
    @parts.each(&:close)
    @io.close
  end
end
